#!/bin/sh
# The single source for the `CI result` job's `needs` list and each gating
# job's required-when condition (`lib/required-jobs.jq`). GitHub Actions
# interpolates `${{ needs }}` before this script could run, so the workflow
# carries a `# needs:` marker generated by `sync` — CI checks the marker is
# current, so neither list can drift.
#
#   check  exit nonzero unless ci.yml's `# needs:` marker lists exactly the
#          jobs `required-jobs.jq` defines (CI result runs this).
#   sync   rewrite the marker; run it after editing required-jobs.jq.
#   jobs   print the job ids, one per line.

set -eu

REPO_ROOT="$(CDPATH='' cd -- "$(dirname -- "$0")/.." && pwd)"
FILTER="$REPO_ROOT/scripts/lib/required-jobs.jq"
CI_YML="$REPO_ROOT/.github/workflows/ci.yml"
MARKER='# needs:'

jobs() {
    jq -n -f "$FILTER" --argjson p '{}' | jq -r 'keys[]' | LC_ALL=C sort | tr '\n' ' ' | sed 's/ *$//'
}

case "${1:-check}" in
    jobs)
        jobs | tr ' ' '\n' | sed '/^$/d'
        ;;
    sync)
        sed -i '' -e "s|^[[:space:]]*${MARKER}.*|  ${MARKER} $(jobs)|" "$CI_YML"
        ;;
    check)
        expected="${MARKER} $(jobs)"
        found="$(grep -E '^[[:space:]]*'"${MARKER}" "$CI_YML" | sed 's/^[[:space:]]*//' || true)"
        if [ "$found" != "$expected" ]; then
            echo "ci.yml '$MARKER' marker drifted: run scripts/ci-required-jobs.sh sync" >&2
            echo "expected: $expected" >&2
            echo "found:    $found" >&2
            exit 1
        fi
        ;;
    *)
        echo "usage: $0 check|sync|jobs" >&2
        exit 2
        ;;
esac
